qss:
QWidget { background: #071b26; color: #e0f5ff; font-family: "Segoe UI", "Inter", sans-serif; font-size: 10pt; }
QMainWindow, QDialog { background: #071b26; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #0c2735; border: 1px solid #285569; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #e0f5ff; }
QLabel#SubtleLabel { color: #82b7c9; }
QPushButton { background: #123d51; color: #e0f5ff; border: 1px solid #285569; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #174d64; }
QPushButton#AccentButton { background: #00a6c8; border: 1px solid #13bddf; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #13bddf; }
QPushButton#DangerButton { background: #583444; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #06151e; color: #e0f5ff; border: 1px solid #285569; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #123f58; border: 1px solid #00a6c8; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #0c2735; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #285569; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #285569; border-radius: 10px; background: #06151e; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #00a6c8; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #0c2735; border: 1px solid #285569; border-left: 4px solid #13bddf; border-radius: 16px; }
QFrame#UserBubbleCard { background: #123f58; border: 1px solid #285569; border-radius: 16px; }
